function getFirebaseAuth(){try{if(!window.firebase)return null;const raw=localStorage.getItem(FIREBASE_CONFIG_KEY);if(!raw)return null;const config=JSON.parse(raw);if(!config.apiKey||!config.authDomain||!config.projectId||!config.appId)return null;if(!firebase.apps.length)firebase.initializeApp(config);return firebase.auth();}catch{return null;}}
