const PUTRI_TUJUH_BIBLE={setting:'Negeri Seri Bunga Tanjung, kerajaan Melayu legendaris di kawasan pesisir Dumai, Riau, pada masa lampau. Jangan menetapkan abad atau tahun tertentu jika tidak disebutkan dalam Master Storyline.',visualStyle:'Historical cinematic realism; cinematic 16:9; muted earthy historical cinema dengan palet warna dan color grading konsisten; detail realistis, pencahayaan sinematik yang sesuai waktu dan lokasi adegan.',languageRules:'Narasi menggunakan Bahasa Indonesia baku dengan nuansa Melayu Riau dan WAJIB dipisahkan dari Google Flow untuk ditambahkan di CapCut menggunakan suara Charon. Google Flow menghasilkan visual, musik latar, ambience, SFX, Foley, dan dialog karakter sesuai storyboard serta voice mapping. Dialog hanya diucapkan karakter yang ditetapkan; jangan menciptakan dialog baru. Hindari slang modern.',continuity:'Master Character Sheet Revisi 02 adalah acuan resmi wajah, busana, aksesori, dan identitas seluruh karakter. Master Storyline menjadi acuan urutan dan kesinambungan cerita. Jangan mengubah identitas wajah, kostum, aksesori, arsitektur, lingkungan, atau color grading tanpa persetujuan produksi. Tampilkan hanya karakter yang ditetapkan tampil dalam klip; karakter narator atau pengisi suara tidak divisualisasikan kecuali storyboard secara eksplisit memerintahkannya.'};
function normalizeBible(p){const b=p.masterBible||{},d=/putri tujuh/i.test(p?.name||'')?PUTRI_TUJUH_BIBLE:{setting:'Setting belum ditentukan dalam Master Bible proyek.',visualStyle:'Cinematic 16:9; ikuti gaya visual proyek yang telah disetujui.',languageRules:'Gunakan bahasa dan aturan dialog yang ditetapkan dalam proyek; jangan menambahkan dialog yang tidak ditentukan.',continuity:'Pertahankan kontinuitas visual dan naratif yang telah disetujui.'};p.masterBible={setting:b.setting?.trim()||d.setting,visualStyle:b.visualStyle?.trim()||d.visualStyle,languageRules:b.languageRules?.trim()||d.languageRules,continuity:b.continuity?.trim()||d.continuity};return p.masterBible}
