function head(kicker,title,desc,action=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function render(){const p=project();let html='';if(activeView==='dashboard')html=dashboard(p);if(activeView==='projects')html=projects();if(activeView==='story')html=storyStudio(p);if(activeView==='characters')html=characters(p);if(activeView==='storyboard')html=storyboard(p);if(activeView==='companion')html=companionStudio(p);if(activeView==='engines')html=engines();$('#app').innerHTML=html;bindDynamic()}
function storageHealth(){const imageCount=state.projects.reduce((n,p)=>n+p.characters.reduce((m,c)=>m+['referenceImage','referenceFront','referenceSide','referenceFullBody'].filter(k=>typeof c[k]==='string'&&c[k]).length,0),0);let size='Tidak tersedia';try{size=(new Blob([localStorage.getItem(KEY)||'']).size/1024/1024).toFixed(2)+' MB'}catch{}return '<div class="panel" style="margin-top:18px"><div class="section-head" style="margin-top:0"><h3>Data & Backup Health</h3><small>Ringkasan lokal perangkat</small></div><div class="stats"><div class="stat"><span>Ukuran data lokal</span><strong>'+size+'</strong></div><div class="stat"><span>Referensi gambar</span><strong>'+imageCount+'</strong></div><div class="stat"><span>Proyek tersimpan</span><strong>'+state.projects.length+'</strong></div></div><p class="small-note">Ukuran ini adalah perkiraan data aplikasi pada localStorage, bukan kapasitas total browser. Backup semua tetap disarankan sebelum impor besar atau perubahan perangkat.</p></div>'}
function dashboard(p){const clips=p?.clips||[],chars=p?.characters||[];return `${head('LPP · PRODUCTION WORKSPACE','Studio produksi sinematik','Ruang kerja terpusat untuk mengembangkan cerita, menjaga kontinuitas karakter, dan menyiapkan produksi film AI.')}<section class="hero"><div><div class="eyebrow">CURRENT PROJECT · ${esc(p?.genre||'FILM PROJECT')}</div><h2>${esc(p?.name||'Belum ada proyek')}</h2><p>${esc(p?.description||'Mulai dengan membuat proyek film pertama Anda.')}</p><button class="btn btn-primary" data-go="storyboard">Buka ruang produksi →</button></div><div class="hero-mark">L</div></section><div class="stats"><div class="stat"><span>Proyek film</span><strong>${state.projects.length}</strong></div><div class="stat"><span>Karakter aktif</span><strong>${chars.length}</strong></div><div class="stat"><span>Klip storyboard</span><strong>${clips.length}</strong></div></div>${storageHealth()}<div class="section-head"><h3>Alur kerja produksi</h3><small>Versi MVP 0.1</small></div><div class="panel"><h3>Master Bible → Storyboard → Prompt → Rendering</h3><p>Susun identitas visual dan aturan karakter terlebih dahulu. Setelah storyboard siap, prompt dapat disalin ke mesin video AI pilihan. Integrasi rendering otomatis akan diaktifkan setelah kredensial provider disiapkan.</p><div class="card-actions"><button class="btn btn-outline" data-go="characters">Kelola karakter</button><button class="btn btn-outline" data-go="engines">Lihat AI engine</button></div></div><div class="section-head"><h3>Proyek terbaru</h3><button class="btn btn-outline btn-small" data-go="projects">Semua proyek</button></div>${state.projects.slice(0,3).map(projectCard).join('')||empty('Belum ada proyek','Buat proyek film pertama untuk memulai.')}`}
